<?php use App\Core\Db; $pdo=Db::pdo(); $id=(int)$_GET['id']; $d=$pdo->query("SELECT * FROM cpms_approval_documents WHERE id=".$id)->fetch(); $lines=$pdo->query("SELECT * FROM cpms_approval_lines WHERE document_id=".$id." ORDER BY line_order")->fetchAll();?><!doctype html><html><body><h1><?php echo h($d['title']);?></h1><div><?php echo nl2br(h($d['content']));?></div><?php foreach($lines as $l):?><div><?php echo h($l['role_type'].' '.$l['approver_name'].' '.$l['line_status'].' '.$l['acted_at']);?></div><?php endforeach;?></body></html>
